```yaml
name: Pre-commit Execute Bot

on:
  issue_comment:
    types: [created]

permissions:
  contents: read

jobs:
  validate_and_dispatch:
    if: github.event.issue.pull_request &&
        (github.event.comment.body == '@github-actions run precommit' ||
         github.event.comment.body == '/precommit')
    runs-on: ubuntu-latest
    permissions:
      contents: read
      pull-requests: read
    steps:
      - name: Check if commenter has write access or is PR author
        id: check_permissions
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const { owner, repo } = context.repo;
            const prNumber = context.issue.number;
            const commenter = context.actor;

            // Get PR info
            const prResponse = await github.rest.pulls.get({
              owner,
              repo,
              pull_number: prNumber
            });

            const prAuthor = prResponse.data.user.login;
            const prHeadSha = prResponse.data.head.sha;

            // Check if commenter is PR author
            if (commenter === prAuthor) {
              console.log("Commenter is PR author");
              return true;
            }

            // Check if commenter has write access to the repo
            try {
              const response = await github.rest.repos.getCollaboratorPermissionLevel({
                owner,
                repo,
                username: commenter
              });
              if (response.data.permission === 'write' || response.data.permission === 'maintain' || response.data.permission === 'admin') {
                console.log("Commenter has write access");
                return true;
              }
            } catch (error) {
              // Not a collaborator, continue to check if it's a fork
            }

            // For forks, check if the PR was created by the same user
            // This is a basic check - in practice, you might want more sophisticated logic
            console.log("Commenter does not have write access or is not PR author");
            return false;

      - name: Dispatch to execution workflow
        if: steps.check_permissions.outputs.result == 'true'
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const { owner, repo } = context.repo;
            const prNumber = context.issue.number;
            const prHeadSha = context.payload.issue.pull_request.head.sha;

            await github.rest.actions.createWorkflowDispatch({
              owner,
              repo,
              workflow_id: 'precommit-execute.yml',
              ref: prHeadSha,
              inputs: {
                pr_number: prNumber.toString(),
                trigger_comment: context.comment.body
              }
            });

  execute_precommit:
    needs: validate_and_dispatch
    if: github.event.workflow_run.event == 'workflow_dispatch' &&
        github.event.workflow_run.conclusion == 'success'
    runs-on: ubuntu-latest
    permissions:
      contents: write
      pull-requests: write
    steps:
      - name: Checkout code
        uses: actions/checkout@v4

      - name: Setup Python
        uses: actions/setup-python@v5
        with:
          python-version: '3.12'

      - name: Install dependencies
        run: |
          pip install pre-commit
          pip install uv

      - name: Run pre-commit
        run: |
          pre-commit run --all-files

      - name: Commit and push changes
        uses: EndBug/add-and-commit@v9
        with:
          message: 'chore: auto-format with pre-commit'
          author_name: 'github-actions[bot]'
          author_email: 'github-actions[bot]@users.noreply.github.com'
          push: true
          branch: ${{ github.event.workflow_run.head_branch }}
          force: true

      - name: Comment on PR
        uses: thollander/actions-comment-pull-request@v2
        with:
          message: |
            ✅ Pre-commit hooks executed successfully. Changes have been committed to this PR.

            If you need further changes, please re-run the command.
          github-token: ${{ secrets.GITHUB_TOKEN }}
          pr-number: ${{ github.event.workflow_run.pull_requests[0].number }}
